import * as React from "react"
import { cn } from "cn"
import { flexRender, type RowData } from "@tanstack/react-table"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { TableHead } from "@/components/ui/table"
import { Icon } from "../icon"
import { useDataTable } from "./context"
import { getPinnedClass, getPinnedStyles } from "./layout"
import type { Column, Header, Table } from "./table-config"
import { getAlignClass, getColumnLabel, isUtilityColumnId } from "./utils"

/** Moves `columnId` next to `targetId` in the column order. */
function reorderColumn(
  table: Table<RowData>,
  columnId: string,
  targetId: string,
  position: "before" | "after"
) {
  const order = table.atoms.columnOrder.get().length
    ? [...table.atoms.columnOrder.get()]
    : table.getAllLeafColumns().map((column) => column.id)
  const from = order.indexOf(columnId)
  if (from < 0) return
  order.splice(from, 1)
  const target = order.indexOf(targetId)
  if (target < 0) return
  order.splice(position === "before" ? target : target + 1, 0, columnId)
  table.setColumnOrder(order)
}

function moveColumn(
  table: Table<RowData>,
  columnId: string,
  direction: "left" | "right"
) {
  const order = table.atoms.columnOrder.get().length
    ? [...table.atoms.columnOrder.get()]
    : table.getAllLeafColumns().map((column) => column.id)
  const index = order.indexOf(columnId)
  const next = direction === "left" ? index - 1 : index + 1
  if (index < 0 || next < 0 || next >= order.length) return
  if (isUtilityColumnId(order[next])) return
  const [id] = order.splice(index, 1)
  order.splice(next, 0, id)
  table.setColumnOrder(order)
}

function ColumnMenu({ column }: { column: Column<RowData, unknown> }) {
  const { table, features, labels } = useDataTable()
  const canSort = features.sorting && column.getCanSort()
  const canPin = features.columnPinning && column.getCanPin()
  const canGroup = features.grouping && column.getCanGroup()
  const canHide = features.columnVisibility && column.getCanHide()
  const canOrder = features.columnOrdering && !isUtilityColumnId(column.id)
  const canResize = features.columnSizing && column.getCanResize()
  const sorted = column.getIsSorted()
  const pinned = column.getIsPinned()

  if (!canSort && !canPin && !canGroup && !canHide && !canOrder) return null

  return (
    <DropdownMenu>
      <DropdownMenuTrigger
        render={
          <Button
            type="button"
            variant="ghost"
            size="icon-xs"
            className="text-subtle opacity-0 group-hover/th:opacity-100 focus-visible:opacity-100 aria-expanded:opacity-100 pointer-coarse:opacity-100"
            aria-label={`${labels.tableOptions}: ${getColumnLabel(column)}`}
          />
        }
      >
        <Icon icon="more" />
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="w-52">
        <DropdownMenuGroup>
          <DropdownMenuLabel>{getColumnLabel(column)}</DropdownMenuLabel>
          {canSort ? (
            <>
              <DropdownMenuItem
                disabled={sorted === "asc"}
                onClick={() => column.toggleSorting(false)}
              >
                <Icon icon="up" className="text-muted-foreground" />
                {labels.sortAscending}
              </DropdownMenuItem>
              <DropdownMenuItem
                disabled={sorted === "desc"}
                onClick={() => column.toggleSorting(true)}
              >
                <Icon icon="down" className="text-muted-foreground" />
                {labels.sortDescending}
              </DropdownMenuItem>
              {sorted ? (
                <DropdownMenuItem onClick={() => column.clearSorting()}>
                  <Icon icon="close" className="text-muted-foreground" />
                  {labels.clearSort}
                </DropdownMenuItem>
              ) : null}
            </>
          ) : null}
          {canGroup ? (
            <DropdownMenuCheckboxItem
              checked={column.getIsGrouped()}
              onCheckedChange={() => column.toggleGrouping()}
            >
              <Icon icon="layers" className="text-muted-foreground" />
              {labels.grouping}
            </DropdownMenuCheckboxItem>
          ) : null}
        </DropdownMenuGroup>
        {canOrder ? (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuItem
                onClick={() => moveColumn(table, column.id, "left")}
              >
                <Icon icon="left" className="text-muted-foreground" />
                {labels.moveLeft}
              </DropdownMenuItem>
              <DropdownMenuItem
                onClick={() => moveColumn(table, column.id, "right")}
              >
                <Icon icon="right" className="text-muted-foreground" />
                {labels.moveRight}
              </DropdownMenuItem>
            </DropdownMenuGroup>
          </>
        ) : null}
        {canPin ? (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              <DropdownMenuItem
                disabled={pinned === "start"}
                onClick={() => column.pin("start")}
              >
                <Icon icon="pin" className="text-muted-foreground" />
                {labels.pinLeft}
              </DropdownMenuItem>
              <DropdownMenuItem
                disabled={pinned === "end"}
                onClick={() => column.pin("end")}
              >
                <Icon icon="pin" className="text-muted-foreground" />
                {labels.pinRight}
              </DropdownMenuItem>
              <DropdownMenuItem
                disabled={!pinned}
                onClick={() => column.pin(false)}
              >
                <Icon icon="close" className="text-muted-foreground" />
                {labels.unpin}
              </DropdownMenuItem>
            </DropdownMenuGroup>
          </>
        ) : null}
        {canResize || canHide ? (
          <>
            <DropdownMenuSeparator />
            <DropdownMenuGroup>
              {canResize ? (
                <DropdownMenuItem onClick={() => column.resetSize()}>
                  <Icon icon="refresh" className="text-muted-foreground" />
                  {labels.resetWidth}
                </DropdownMenuItem>
              ) : null}
              {canHide ? (
                <DropdownMenuItem
                  onClick={() => column.toggleVisibility(false)}
                >
                  <Icon icon="view" className="text-muted-foreground" />
                  {labels.hideColumn}
                </DropdownMenuItem>
              ) : null}
            </DropdownMenuGroup>
          </>
        ) : null}
      </DropdownMenuContent>
    </DropdownMenu>
  )
}

/** Sortable, draggable label with sort order and filter indicators. */
function ColumnLabel({ header }: { header: Header<RowData, unknown> }) {
  const { table, features, setDraggingColumnId } = useDataTable()
  const column = header.column
  const sorted = column.getIsSorted()
  const canSort = features.sorting && column.getCanSort()
  const align = column.columnDef.meta?.align
  const content = flexRender(column.columnDef.header, header.getContext())
  const sortCount = table.atoms.sorting.get().length
  const sortIndex = column.getSortIndex()
  const canDrag =
    features.columnDragging &&
    features.columnOrdering &&
    !isUtilityColumnId(column.id) &&
    !column.getIsPinned()

  return (
    <div
      className={cn(
        "flex w-full min-w-0 items-center gap-1",
        align === "right" && "flex-row-reverse",
        align === "center" && "justify-center",
        canDrag && "cursor-grab active:cursor-grabbing"
      )}
      draggable={canDrag || undefined}
      onDragStart={(event) => {
        event.dataTransfer.setData("text/plain", column.id)
        event.dataTransfer.effectAllowed = "move"
        setDraggingColumnId(column.id)
      }}
      onDragEnd={() => setDraggingColumnId(null)}
    >
      {canSort ? (
        <button
          type="button"
          className={cn(
            "flex min-w-0 items-center gap-1 rounded-(--radius-item) transition-colors hover:text-foreground",
            align === "right" && "flex-row-reverse",
            sorted && "text-foreground"
          )}
          onClick={column.getToggleSortingHandler()}
          title={
            features.multiSort
              ? "Shift-click to sort by several columns"
              : undefined
          }
        >
          <span className="truncate">{content}</span>
          <Icon
            icon={sorted === "asc" ? "up" : sorted === "desc" ? "down" : "sort"}
            size={13}
            className={cn("shrink-0", !sorted && "text-subtle")}
          />
          {sorted && sortCount > 1 ? (
            <span className="text-4xs text-subtle tabular-nums">
              {sortIndex + 1}
            </span>
          ) : null}
        </button>
      ) : (
        <span className="min-w-0 truncate">{content}</span>
      )}
      {column.getIsFiltered() ? (
        <Icon
          icon="filter"
          size={12}
          className="shrink-0 text-focus"
          aria-label="Filtered"
        />
      ) : null}
    </div>
  )
}

/**
 * A header cell: leaf columns get the sortable label, column menu, drag
 * target and resize handle; group columns get a centered caption.
 */
function HeaderCell({
  header,
  isGroupRow,
}: {
  header: Header<RowData, unknown>
  isGroupRow: boolean
}) {
  const { table, features, draggingColumnId, setDraggingColumnId } =
    useDataTable()
  const [dropSide, setDropSide] = React.useState<"before" | "after" | null>(
    null
  )
  const column = header.column
  const meta = column.columnDef.meta
  const isGroup = !header.isPlaceholder && header.subHeaders.length > 0
  const canDrop =
    !header.isPlaceholder &&
    draggingColumnId !== null &&
    draggingColumnId !== column.id &&
    !isGroup &&
    !isUtilityColumnId(column.id) &&
    !column.getIsPinned()

  return (
    <TableHead
      colSpan={header.colSpan}
      data-drop={dropSide ?? undefined}
      aria-sort={
        !isGroup && column.getCanSort()
          ? column.getIsSorted() === "asc"
            ? "ascending"
            : column.getIsSorted() === "desc"
              ? "descending"
              : "none"
          : undefined
      }
      className={cn(
        "group/th relative px-[17px] align-middle text-2xs font-normal text-muted-foreground",
        isGroupRow
          ? "h-[34px] group-data-[density=compact]/data-table:h-7"
          : "h-[45px] group-data-[density=compact]/data-table:h-[34px]",
        isGroup &&
          "border-x border-b text-left font-medium text-foreground first:border-l-0 last:border-r-0",
        !isGroup && getAlignClass(meta?.align),
        isUtilityColumnId(column.id) && "px-0 text-center",
        draggingColumnId === column.id && "opacity-50",
        "data-[drop=after]:shadow-[inset_-2px_0_0_var(--focus)] data-[drop=before]:shadow-[inset_2px_0_0_var(--focus)]",
        getPinnedClass(column),
        meta?.headerClassName,
        meta?.className
      )}
      style={getPinnedStyles(column)}
      onDragOver={(event) => {
        if (!canDrop) return
        event.preventDefault()
        const rect = event.currentTarget.getBoundingClientRect()
        setDropSide(
          event.clientX < rect.left + rect.width / 2 ? "before" : "after"
        )
      }}
      onDragLeave={() => setDropSide(null)}
      onDrop={(event) => {
        if (!canDrop || !draggingColumnId || !dropSide) return
        event.preventDefault()
        reorderColumn(table, draggingColumnId, column.id, dropSide)
        setDropSide(null)
        setDraggingColumnId(null)
      }}
    >
      {header.isPlaceholder ? null : isGroup ? (
        // Sticks beside the pinned columns so wide groups stay labelled.
        <span
          className="sticky inline-block max-w-full truncate align-middle"
          style={{
            insetInlineStart: column.getIsPinned()
              ? undefined
              : table.getStartTotalSize() + 17,
          }}
        >
          {flexRender(column.columnDef.header, header.getContext())}
        </span>
      ) : (
        <>
          <ColumnLabel header={header} />
          {/* Overlaid on the side away from the label so it never truncates
              it; its backing shows only with the menu, so at rest it never
              covers a long label's sort icon either. */}
          <span
            className={cn(
              "absolute top-1/2 flex -translate-y-1/2 rounded-(--radius-control) group-hover/th:bg-background focus-within:bg-background has-aria-expanded:bg-background pointer-coarse:bg-background",
              meta?.align === "right" ? "left-2" : "right-2"
            )}
          >
            <ColumnMenu column={column} />
          </span>
        </>
      )}
      {features.columnSizing &&
      !header.isPlaceholder &&
      column.getCanResize() ? (
        <button
          type="button"
          aria-label={`Resize ${getColumnLabel(column)}`}
          title="Drag to resize, double-click to reset"
          className={cn(
            "absolute top-2 right-0 bottom-2 w-[3px] cursor-col-resize touch-none rounded-full bg-transparent transition-colors select-none group-hover/th:bg-border hover:bg-focus/60",
            column.getIsResizing() && "bg-focus"
          )}
          onMouseDown={header.getResizeHandler()}
          onTouchStart={header.getResizeHandler()}
          onDoubleClick={() => column.resetSize()}
        />
      ) : null}
    </TableHead>
  )
}

export { HeaderCell }

import type * as React from "react"
import { cn } from "cn"
import type { RowData } from "@tanstack/react-table"

import type { Column, Table } from "./table-config"
import { isUtilityColumnId } from "./utils"

/** The filter row and detail rows share this faint surface. */
export const subtleSurface =
  "bg-[color-mix(in_oklch,var(--muted)_35%,var(--background))]"

/* Row heights follow the task list: 45px, or 34px when compact. */
export const cellHeight =
  "h-[45px] py-2 group-data-[density=compact]/data-table:h-[34px] group-data-[density=compact]/data-table:py-1"

export const rowHeightPx = { default: 45, compact: 34 } as const

// Keep pinned and utility columns at their measured TanStack sizes. One
// unpinned data column fills spare space without shifting sticky offsets.
export function getFlexibleColumn<TData extends RowData>(table: Table<TData>) {
  const sizing = table.atoms.columnSizing.get()
  return table
    .getCenterVisibleLeafColumns()
    .find(
      (column) =>
        !isUtilityColumnId(column.id) && sizing[column.id] === undefined
    )
}

/** Sticky offsets for pinned columns. Widths come from the table's <colgroup>. */
export function getPinnedStyles<TData extends RowData>(
  column: Column<TData, unknown>
): React.CSSProperties {
  const isPinned = column.getIsPinned()
  return {
    insetInlineStart:
      isPinned === "start" ? `${column.getStart("start")}px` : undefined,
    insetInlineEnd:
      isPinned === "end" ? `${column.getAfter("end")}px` : undefined,
    position: isPinned ? "sticky" : "relative",
    zIndex: isPinned ? 3 : 0,
  }
}

/**
 * Pinned cells are sticky, so they paint their own surface: the header's,
 * the filter row's, or the body row's (including hover, selected and pinned).
 */
export function getPinnedClass<TData extends RowData>(
  column: Column<TData, unknown>,
  surface: "head" | "filter" | "body" = "head"
) {
  const isPinned = column.getIsPinned()

  return cn(
    isPinned && surface === "head" && "bg-background",
    isPinned && surface === "filter" && subtleSurface,
    isPinned &&
      surface === "body" &&
      "bg-background group-hover/row:bg-[color-mix(in_oklch,var(--muted)_60%,var(--background))] group-data-[pinned]/row:bg-[color-mix(in_oklch,var(--muted)_45%,var(--background))] group-data-[state=selected]/row:bg-muted",
    isPinned === "start" &&
      column.getIsLastColumn("start") &&
      "border-r shadow-[1px_0_0_var(--border)]",
    isPinned === "end" &&
      column.getIsFirstColumn("end") &&
      "border-l shadow-[-1px_0_0_var(--border)]"
  )
}

import * as React from "react"
import type { RowData } from "@tanstack/react-table"

import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"
import { Icon } from "../icon"
import { useDataTable } from "./context"
import type { Table } from "./table-config"
import { formatValue, isDateColumn, selectionStats } from "./utils"

const count = (value: number) => formatValue(value, { format: "integer" })
const stat = (value: number) =>
  formatValue(value, {
    format: "number",
    formatOptions: { maximumFractionDigits: 2 },
  })

/** Selected values from number columns; timestamps in date columns don't add up. */
function numericValues(table: Table<RowData>) {
  const columnIds = table.getCellSelectionColumnIds().filter((id) => {
    const column = table.getColumn(id)
    return column && !isDateColumn(column)
  })
  const values: unknown[] = []
  for (const rowId of table.getCellSelectionRowIds()) {
    const cells = table.getRow(rowId, true)?.getAllCellsByColumnId()
    if (!cells) continue
    for (const columnId of columnIds) {
      const cell = cells[columnId]
      if (cell?.getIsSelected()) values.push(cell.getValue())
    }
  }
  return values
}

/** Count / Sum / Avg / Min / Max of the selected cells. */
function SelectionSummary() {
  const { table, features } = useDataTable()
  const selectedCells = features.cellSelection
    ? table.getSelectedCellCount()
    : 0
  if (selectedCells < 2) return null
  // Very large ranges would stall the render; the count is enough there.
  const stats =
    selectedCells <= 100_000 ? selectionStats(numericValues(table)) : undefined
  const items: Array<[string, string]> = [["Count", count(selectedCells)]]
  if (stats && stats.numeric > 0) {
    items.push(
      ["Sum", stat(stats.sum ?? 0)],
      ["Avg", stat(stats.mean ?? 0)],
      ["Min", stat(stats.min ?? 0)],
      ["Max", stat(stats.max ?? 0)]
    )
  }
  return (
    <dl className="flex flex-wrap items-center gap-x-3 gap-y-1 tabular-nums">
      {items.map(([label, value]) => (
        <div key={label} className="flex items-baseline gap-1">
          <dt className="text-subtle">{label}</dt>
          <dd className="text-foreground">{value}</dd>
        </div>
      ))}
    </dl>
  )
}

function Pagination() {
  const { table, labels } = useDataTable()
  const pageSizeId = React.useId()
  const { pageIndex, pageSize } = table.atoms.pagination.get()
  const pageSizes = [...new Set([10, 20, 30, 40, 50, 100, pageSize])].sort(
    (a, b) => a - b
  )
  return (
    <div className="flex flex-wrap items-center gap-[7px]">
      <Label
        className="text-2xs font-normal text-muted-foreground"
        htmlFor={pageSizeId}
      >
        {labels.rowsPerPage}
      </Label>
      <Select<number>
        value={pageSize}
        onValueChange={(value) => {
          if (value !== null) table.setPageSize(value)
        }}
        items={pageSizes.map((value) => ({ value, label: String(value) }))}
      >
        <SelectTrigger id={pageSizeId} size="sm" className="w-[70px] text-xs">
          <SelectValue />
        </SelectTrigger>
        <SelectContent alignItemWithTrigger={false}>
          <SelectGroup>
            {pageSizes.map((value) => (
              <SelectItem key={value} value={value}>
                {value}
              </SelectItem>
            ))}
          </SelectGroup>
        </SelectContent>
      </Select>
      <div className="min-w-24 text-center tabular-nums">
        {labels.page} <span className="text-foreground">{pageIndex + 1}</span>{" "}
        {labels.of} {Math.max(1, table.getPageCount())}
      </div>
      <Button
        type="button"
        variant="outline"
        size="icon-sm"
        aria-label={labels.firstPage}
        onClick={() => table.setPageIndex(0)}
        disabled={!table.getCanPreviousPage()}
      >
        <Icon icon="left" />
      </Button>
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={() => table.previousPage()}
        disabled={!table.getCanPreviousPage()}
      >
        {labels.previousPage}
      </Button>
      <Button
        type="button"
        variant="outline"
        size="sm"
        onClick={() => table.nextPage()}
        disabled={!table.getCanNextPage()}
      >
        {labels.nextPage}
      </Button>
      <Button
        type="button"
        variant="outline"
        size="icon-sm"
        aria-label={labels.lastPage}
        onClick={() => table.setPageIndex(table.getPageCount() - 1)}
        disabled={!table.getCanNextPage()}
      >
        <Icon icon="right" />
      </Button>
    </div>
  )
}

/**
 * Row counts, selection, selected-cell statistics and pagination under the
 * grid. `notice` briefly confirms actions such as copying; `actions` are the
 * table's own controls at its end.
 */
function DataTableStatusBar({
  notice,
  actions,
}: {
  notice: string | null
  actions?: React.ReactNode
}) {
  const { table, features, labels, treeData } = useDataTable()
  const paged = features.pagination && !features.virtualization
  const manual = Boolean(table.options.manualFiltering)
  // Tree data counts every node, not just the roots.
  const filtered = table.getFilteredRowModel()
  const total =
    table.options.rowCount ??
    (treeData ? filtered.flatRows.length : filtered.rows.length)
  const core = table.getCoreRowModel()
  const unfiltered = treeData ? core.flatRows.length : core.rows.length
  // Every selected row, sub-rows too: a tree's `rows` holds only those
  // whose parents are selected.
  const selectedRows = features.rowSelection
    ? table.getFilteredSelectedRowModel().flatRows.length
    : 0
  const { pageIndex, pageSize } = table.atoms.pagination.get()
  const pageTotal = table.getRowCount()
  const first = pageTotal ? pageIndex * pageSize + 1 : 0
  const last = Math.min((pageIndex + 1) * pageSize, pageTotal)
  const rowsLabel =
    total === 1 ? labels.rowSingular || labels.rows : labels.rows

  return (
    <div
      data-slot="data-table-pagination"
      className="flex flex-col gap-2.5 border-t px-4 py-2.5 text-2xs text-muted-foreground @2xl/data-table:flex-row @2xl/data-table:items-center @2xl/data-table:justify-between"
    >
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
        <div className="tabular-nums">
          {features.rowSelection ? (
            <>
              <span className="text-foreground">{count(selectedRows)}</span>{" "}
              {labels.rowsSelected} ·{" "}
            </>
          ) : null}
          {paged && pageTotal > pageSize ? (
            <>
              {labels.showing}{" "}
              <span className="text-foreground">
                {count(first)}–{count(last)}
              </span>{" "}
              {labels.of}{" "}
            </>
          ) : null}
          <span className="text-foreground">{count(total)}</span> {rowsLabel}
          {!manual && total < unfiltered ? (
            <span className="text-subtle">
              {" "}
              ({labels.of} {count(unfiltered)})
            </span>
          ) : null}
        </div>
        {features.statusBar ? <SelectionSummary /> : null}
        <span role="status" aria-live="polite" className="text-foreground">
          {notice ? (
            <span className="inline-flex items-center gap-1">
              <Icon
                icon="check"
                size={12}
                className="text-success-foreground"
              />
              {notice}
            </span>
          ) : null}
        </span>
      </div>
      {actions ? (
        <div className="flex flex-wrap items-center gap-2">{actions}</div>
      ) : null}
      {paged ? <Pagination /> : null}
    </div>
  )
}

