export function createRowNumberColumn<TData extends RowData>(
  labels: DataTableLabels
): ColumnDef<TData, unknown> {
  return {
    ...utilityColumn,
    id: "__row_number",
    size: 52,
    minSize: 52,
    maxSize: 52,
    header: () => labels.rowNumber,
